import type { MetadataRoute } from "next";
import { SITE_PAGES } from "@/lib/site-pages";
import { SITE_URL } from "@/lib/kost-facts";
import lastmod from "@/lib/page-lastmod.json";

/**
 * One entry per public page. lastModified = date of the last commit touching
 * the page file (generated by scripts/generate-page-lastmod.mjs), never the
 * build date. Pages without a known date are emitted without lastmod.
 */
export default function sitemap(): MetadataRoute.Sitemap {
  const base = process.env.NEXT_PUBLIC_SITE_URL || SITE_URL;
  const dates = lastmod as Record<string, string>;

  return SITE_PAGES.map((page) => {
    const languages = page.alt
      ? {
          fr: `${base}${page.lang === "fr" ? page.path : page.alt}`,
          en: `${base}${page.lang === "en" ? page.path : page.alt}`,
          "x-default": `${base}${page.lang === "fr" ? page.path : page.alt}`,
        }
      : undefined;
    return {
      url: `${base}${page.path}`,
      ...(dates[page.path] ? { lastModified: new Date(dates[page.path]) } : {}),
      changeFrequency: page.changeFrequency,
      priority: page.priority,
      ...(languages ? { alternates: { languages } } : {}),
    };
  });
}
